def action_data():
    strings = bytearray()
    pointers = bytearray()
    fixups = {}
    for name in ACTION_NAMES:
        offset = 4 + len(strings)
        fixups[0xA93D0 + len(pointers)] = (7, 0, 3, offset)
        pointers.extend(struct.pack("<I", offset))
        strings.extend(name.encode("ascii") + b"\0")
        strings.extend(bytes(-len(strings) % 4))
    return strings, pointers, fixups


def script_keyword_data():
    keywords = b"""
        definelevelname actor addammo ifrnd enda ifcansee ifhitweapon action
        ifpdistl ifpdistg else strength break shoot palfrom sound fall state ends define
        // ifai killit addweapon ai addphealth ifdead ifsquished sizeto { } spawn move
        ifwasweapon ifaction ifactioncount resetactioncount debris pstomp /* cstat
        ifmove resetplayer ifonwater ifinwater ifcanshoottarget ifcount resetcount
        addinventory ifactornotstayput hitradius ifp count ifactor music include
        ifstrength definesound guts ifspawnedby gamestartup wackplayer ifgapzl
        ifhitspace ifoutside ifmultiplayer operate ifinspace debug endofgame ifbulletnear
        ifrespawn iffloordistl ifceilingdistl spritepal ifpinventory betaname cactor
        ifphealthl definequote quote ifinouterspace ifnotmoving respawnhitag tip
        ifspritepal feathers soundonce addkills stopsound ifawayfromwall ifcanseetarget
        globalsound lotsofglass ifgotweaponce getlastpal pkick mikesnd useractor
        sizeat addstrength cstator mail paper tossweapon sleeptime nullop
        definevolumename defineskillname ifnosounds ifnocover iffindnewspot iftipcow
        isdrunk iseat destroyit leavetrax strafeleft straferight ifactorhealthg
        ifactorhealthl slapplayer ifpdrunk leavedroppings deploybias soundtagonce
        soundtag ifsoundid ifsounddist ifonmud ifcoop ifmotofast ifpupwind smacksprite
        ifonmoto ifonboat fakebubba mamatrigger mamaspawn mamaquake clipdist mamaend
        newpic garybanjo motoloopsnd ifsizedown rndmove GAME.CON USER.CON DEFS.CON
    """.split()
    strings = bytearray()
    pointers = bytearray()
    fixups = {}
    for keyword in keywords:
        target = 0x1788 + len(strings)
        fixups[0xA9730 + len(pointers)] = (7, 0, 3, target)
        pointers.extend(struct.pack("<I", target))
        strings.extend(keyword + bytes(4 - len(keyword) % 4))
    return strings, pointers, fixups


def default_binding_data():
    actions = (
        b"Move_Forward Move_Backward Turn_Left Turn_Right Strafe Strafe_Left Strafe_Right "
        b"TurnAround Jump Crouch Fire Open Look_Up Look_Down Aim_Up Aim_Down Run SendMessage"
    ).split() + [f"Weapon_{n}".encode() for n in range(1, 11)] + (
        b"Pause Map Look_Left Look_Right Gamma_Correction Escape Shrink_Screen Enlarge_Screen "
        b"ScreenPeek Transparent_Mode AutoRun Virtual_Mode Center_View Holster_Weapon "
        b"Inventory_Left Inventory_Right Beer Moon_Pie Powerup_Toggle Inventory"
    ).split() + [f"Remote_Ridicule_{n}".encode() for n in range(1, 11)] + [b"Cross_Hair_Toggle"]
    keys = (
        b"Up Kpad8 Down Kpad2 Left Kpad4 Right Kpad6 LAlt RAlt ,"
    ).split() + [b""] + (
        b". BakSpc A Z LCtrl RCtrl Space PgUp PgDn Home End LShift RShift T "
        b"1 2 3 4 5 6 7 8 9 0 Tab [ ] F11 - Kpad- = Kpad+ K W CapLck V KPad5 KpdEnt O B X Enter "
        b"F1 F2 F3 F4 F5 F6 F7 F8 F9 F10 C"
    ).split()
    strings = bytearray()
    offsets = {}
    for name in actions + keys:
        offsets[name] = 0x3584 + len(strings)
        strings.extend(name + bytes(4 - len(name) % 4))

    bindings = (
        b"Up/Kpad8 Down/Kpad2 Left/Kpad4 Right/Kpad6 LAlt/RAlt , . BakSpc A Z LCtrl/RCtrl "
        b"Space PgUp PgDn Home End LShift/RShift T 1 2 3 4 5 6 7 8 9 0 Pause Tab [ ] F11 "
        b"Escape -/Kpad- =/Kpad+ K W CapLck V KPad5 KpdEnt [ ] O B X Enter "
        b"F1 F2 F3 F4 F5 F6 F7 F8 F9 F10 C"
    ).split()
    keyboard_actions = list(actions)
    beer = keyboard_actions.index(b"Beer")
    keyboard_actions[beer:beer + 2] = [b"Moon_Pie", b"Beer"]
    names = list(actions)
    for action, binding in zip(keyboard_actions, bindings, strict=True):
        primary, _, secondary = binding.partition(b"/")
        names.extend((action, primary, secondary))
    names.extend([b"Fire", b"Strafe", b"Move_Forward", b"", b"Open"] + [b""] * 9)
    targets = [offsets[name] for name in names]
    fixups = {0xA99F0 + 4 * index: (7, 0, 3, target) for index, target in enumerate(targets)}
    return strings, struct.pack(f"<{len(targets)}I", *targets), fixups


def initialized_defaults():
    configuration = bytearray(0x290)
    configuration[:11] = b"HUNTING.CFG"
    configuration[0x98:0xA0] = b"GAME.CON"
    struct.pack_into("<i", configuration, 0x1F0, -1)
    struct.pack_into("<i", configuration, 0x204, -1)
    credits = (
        b"Redneck Ramage Rides Again(tm) Copyright 1997 Xatrix Entertainment\0"
        b"I want to make a game with trees\0"
        b"16 Possible Rednecks\0"
    )
    configuration[0x208:0x208 + len(credits)] = credits
    struct.pack_into("<II", configuration, 0x284, 1, 1)
    level_defaults = bytearray(0x68)
    struct.pack_into("<HHH", level_defaults, 4, 0xFFFF, 0, 1)
    struct.pack_into("<H", level_defaults, 0x10, 0xFFFF)
    struct.pack_into("<H", level_defaults, 0x60, 9)
    return (
        ("startup_flags", 0xA0000, bytes((1, 1, 1, 0)), {}),
        ("game_configuration_defaults", 0xA94A0, configuration, {}),
        ("level_defaults", 0xA9988, level_defaults, {}),
        ("audio_code_alignment", 0x7D624, bytes(12), {}),
        ("audio_data_pointer", 0xB393C, struct.pack("<I", 0x854C),
         {0xB393C: (7, 0, 3, 0x854C)}),
    )


